1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	// Kept as a separate additive term rather than folded into a `policyBase * 1.1`
51	// factor: that is not float-equivalent (100 * 1.1 === 110.00000000000001), and
52	// the final rounding-up turns the stray ulp into a whole extra gold piece.
53	// Do not "simplify".
54	const firstInsuranceSurcharge = (policyBase: number): number =>
55	  policyBase * FIRST_INSURANCE_RATE;
56	
57	// The MHPCO rounds premiums in its own favour: up.
58	const premiumRoundedInMHPCOsFavour = (premium: number): number =>
59	  Math.ceil(premium);
60	
61	const COMPONENT_BLOCK_SIZE = 3;
62	const COMPONENT_BLOCK_PREMIUM = 60;
63	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
64	
65	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
66	
67	// A group is every item of one single type, so a group is always non-empty
68	// and homogeneous — the block rule below relies on both.
69	interface TypeGroup {
70	  type: string;
71	  items: Item[];
72	}
73	
74	const groupByType = (items: Item[]): TypeGroup[] =>
75	  [
76	    ...items.reduce(
77	      (groups, item) =>
78	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
79	      new Map<string, Item[]>(),
80	    ),
81	  ].map(([type, groupedItems]) => ({ type, items: groupedItems }));
82	
83	const formsComponentBlock = (group: TypeGroup): boolean =>
84	  group.items.length === COMPONENT_BLOCK_SIZE && COMPONENT_TYPES.has(group.type);
85	
86	const sumOfItemBasePremiums = (items: Item[]): number =>
87	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
88	
89	const groupBasePremium = (group: TypeGroup): number =>
90	  formsComponentBlock(group)
91	    ? COMPONENT_BLOCK_PREMIUM
92	    : sumOfItemBasePremiums(group.items);
93	
94	const policyBasePremium = (items: Item[]): number =>
95	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
96	
97	const CURSE_SURCHARGE_RATE = 0.5;
98	
99	// Item-specific modifiers are charged on the affected item's own base premium,
100	// unlike the policy-wide modifiers which apply to the sum of all of them.
101	const curseSurcharge = (item: Item): number =>
102	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
103	
104	const HIGH_ENCHANTMENT_LEVEL = 5;
105	const HIGH_ENCHANTMENT_RATE = 0.3;
106	
107	// An unenchanted item may leave `enchantment` unset; absent means level 0.
108	const isHighlyEnchanted = (item: Item): boolean =>
109	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
110	
111	const highEnchantmentSurcharge = (item: Item): number =>
112	  isHighlyEnchanted(item) ? basePremiumOf(item) * HIGH_ENCHANTMENT_RATE : 0;
113	
114	const itemSurcharge = (item: Item): number =>
115	  curseSurcharge(item) + highEnchantmentSurcharge(item);
116	
117	const totalItemSurcharges = (items: Item[]): number =>
118	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
119	
120	const LOYALTY_YEARS = 2;
121	const LOYALTY_DISCOUNT_RATE = 0.2;
122	
123	const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
124	  customer.yearsWithMHPCO >= LOYALTY_YEARS
125	    ? policyBase * LOYALTY_DISCOUNT_RATE
126	    : 0;
127	
128	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
129	
130	// Every contract after the customer's first is a follow-up. Which contract
131	// this is depends on how many quotes preceded it in the scenario, not on the
132	// customer record.
133	const followUpDiscount = (precedingQuotes: number, policyBase: number): number =>
134	  precedingQuotes > 0 ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
135	
136	// Everything a step needs beyond its own payload: who is buying, where in the
137	// scenario the step sits, and the surrounding steps a claim resolves its
138	// `policy` reference against. Bundled so callers thread one named value rather
139	// than a trail of bare parameters.
140	interface StepContext {
141	  customer: Customer;
142	  precedingQuotes: number;
143	  steps: Step[];
144	}
145	
146	// Policy-wide modifiers are charged on the sum of all item base premiums,
147	// unlike the item-specific ones above. Each returns a signed adjustment:
148	// surcharges positive, discounts negative.
149	const policyModifiers = (policyBase: number, context: StepContext): number =>
150	  firstInsuranceSurcharge(policyBase) -
151	  loyaltyDiscount(context.customer, policyBase) -
152	  followUpDiscount(context.precedingQuotes, policyBase);
153	
154	const quotePremium = (items: Item[], context: StepContext): number => {
155	  const policyBase = policyBasePremium(items);
156	  return premiumRoundedInMHPCOsFavour(
157	    policyBase +
158	      policyModifiers(policyBase, context) +
159	      totalItemSurcharges(items) +
160	      PROCESSING_FEE,
161	  );
162	};
163	
164	const DEDUCTIBLE = 100;
165	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
166	  sword: 1000,
167	  amulet: 600,
168	  staff: 800,
169	  potion: 400,
170	  rune: 250,
171	  moonstone: 250,
172	};
173	const CAP_MULTIPLE = 2;
174	
175	// And payouts in its own favour too: down.
176	const payoutRoundedInMHPCOsFavour = (payout: number): number =>
177	  Math.floor(payout);
178	
179	const insuranceSum = (items: Item[]): number =>
180	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
181	
182	const capOf = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLE;
183	
184	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
185	const HIGH_ENCHANTMENT_CLAIM_RATE = 0.5;
186	
187	// Highly enchanted items are notoriously hard to appraise, so the MHPCO
188	// reimburses only half their damage.
189	const coveredAmount = (damage: Damage, item: Item): number =>
190	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL
191	    ? damage.amount * HIGH_ENCHANTMENT_CLAIM_RATE
192	    : damage.amount;
193	
194	const reimbursement = (damage: Damage, item: Item): number =>
195	  coveredAmount(damage, item) - DEDUCTIBLE;
196	
197	const damagedItem = (insuredItems: Item[], damage: Damage): Item => {
198	  const item = insuredItems.find(({ type }) => type === damage.itemType);
199	  if (item === undefined) {
200	    throw new Error(`${damage.itemType} is not insured by this policy`);
201	  }
202	  return item;
203	};
204	
205	const claimPayout = (incident: Incident, insuredItems: Item[]): number =>
206	  payoutRoundedInMHPCOsFavour(
207	    incident.damages.reduce(
208	      (total, damage) =>
209	        total + reimbursement(damage, damagedItem(insuredItems, damage)),
210	      0,
211	    ),
212	  );
213	
214	const insuredItemsOf = (steps: Step[], policy: number): Item[] => {
215	  const policyStep = steps[policy];
216	  if (policyStep.op !== "quote") {
217	    throw new Error(`step ${policy} is not a quote`);
218	  }
219	  return policyStep.items;
220	};
221	
222	const runStep = (step: Step, context: StepContext): StepResult => {
223	  if (step.op === "quote") {
224	    return { premium: quotePremium(step.items, context) };
225	  }
226	  const insuredItems = insuredItemsOf(context.steps, step.policy);
227	  const payout = claimPayout(step.incident, insuredItems);
228	  return { payout, remainingCap: capOf(insuredItems) - payout };
229	};
230	
231	const countQuotes = (steps: Step[]): number =>
232	  steps.filter((step) => step.op === "quote").length;
233	
234	export const runScenario = (scenario: Scenario): ScenarioResult => ({
235	  results: scenario.steps.map((step, index) =>
236	    runStep(step, {
237	      customer: scenario.customer,
238	      precedingQuotes: countQuotes(scenario.steps.slice(0, index)),
239	      steps: scenario.steps,
240	    }),
241	  ),
242	});
