316	describe("MHPCO Claim Office — quote: rounding in the MHPCO's favor", () => {
317	  it("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)", () => {
318	    const result = runScenario({
319	      customer: { yearsWithMHPCO: 0 },
320	      steps: [
321	        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
322	      ],
323	    });
324	
325	    // 175 G base + 17.5 G first insurance + 5 G fee = 197.5 G exactly — a
326	    // half-gold amount, rounded up rather than to the nearest whole G.
327	    expect(result).toEqual({ results: [{ premium: 198 }] });
328	  });
329	  it("intermediate amounts are kept as fractions; only the final premium is rounded", () => {
330	    const result = runScenario({
331	      customer: { yearsWithMHPCO: 0 },
332	      steps: [
333	        { op: "quote", items: [{ type: "potion", material: "glass" }] },
334	        { op: "quote", items: Array.from({ length: 5 }, () => ({ type: "rune" })) },
335	      ],
336	    });
337	
338	    // second quote: 125 G base, +12.5 G first insurance, −18.75 G follow-up,
339	    // +5 G fee = 123.75 G → 124 G. Both modifiers are fractional and neither
340	    // is rounded on its own: rounding 12.5 up to 13 and 18.75 up to 19 would
341	    // give 124 by luck, but truncating each toward zero would give 124 too —
